from datetime import date, timedelta


class Loyalty:
    def __init__(self) -> None:
        # customer -> list of (available_on_date, points)
        self._pending: dict[str, list[tuple[date, int]]] = {}
        # customer -> list of (spent_on_date, points) for redeemed points
        self._redeemed: dict[str, list[tuple[date, int]]] = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        if amount <= 0:
            raise ValueError("Purchase amount must be positive")
        points = int(amount // 10)
        if points > 0:
            self._pending.setdefault(customer, []).append(
                (day + timedelta(days=14), points)
            )
        return points

    def _available(self, customer: str, day: date) -> int:
        earned = sum(
            pts for avail, pts in self._pending.get(customer, [])
            if avail <= day
        )
        spent = sum(
            pts for spent_day, pts in self._redeemed.get(customer, [])
            if spent_day <= day
        )
        return earned - spent

    def balance(self, customer: str, day: date) -> int:
        return self._available(customer, day)

    def redeem(self, customer: str, points: int, day: date) -> None:
        if points <= 0 or points % 100 != 0:
            raise ValueError("Points must be redeemed in multiples of 100")
        if points > self._available(customer, day):
            raise ValueError("Insufficient points")
        self._redeemed.setdefault(customer, []).append((day, points))
